/* eslint-disable @typescript-eslint/no-explicit-any */
import { ImageService } from 'mapbox-gl-esri-sources';

export class LoggingImageService {
  private _service: any;

  constructor(sourceId: any, map: any, esriServiceOptions: any, rasterSrcOptions: any) {
    console.log(`[LoggingImageService] constructor called for ${sourceId}`, { esriServiceOptions, rasterSrcOptions });
    
    this._service = new ImageService(sourceId, map, esriServiceOptions, rasterSrcOptions);
    
    // Monkey patch _updateSource to log it when called internally
    const originalUpdateSource = this._service._updateSource.bind(this._service);
    this._service._updateSource = () => {
      console.log(`[LoggingImageService] _updateSource called (internal)`);
      originalUpdateSource();
    };
  }

  get esriServiceOptions() {
    return this._service.esriServiceOptions;
  }
  
  set esriServiceOptions(value) {
    this._service.esriServiceOptions = value;
  }

  setDate(from: any, to: any) {
    console.log(`[LoggingImageService] setDate called`, { from, to });
    this._service.setDate(from, to);
  }

  setRenderingRule(rule: any) {
    console.log(`[LoggingImageService] setRenderingRule called`, { rule });
    this._service.setRenderingRule(rule);
  }

  setMosiacRule(rule: any) {
    console.log(`[LoggingImageService] setMosiacRule called`, { rule });
    this._service.setMosiacRule(rule);
  }

  getMetadata() {
    console.log(`[LoggingImageService] getMetadata called`);
    return this._service.getMetadata().then((res: any) => {
      console.log(`[LoggingImageService] getMetadata result`, res);
      return res;
    });
  }

  identify(lnglat: any, returnGeometry: any) {
    console.log(`[LoggingImageService] identify called`, { lnglat, returnGeometry });
    return this._service.identify(lnglat, returnGeometry);
  }
  
  _updateSource() {
    console.log(`[LoggingImageService] _updateSource called (external wrapper)`);
    this._service._updateSource();
  }
}
